using ElectroMart.API.Data; using ElectroMart.API.DTOs; using ElectroMart.API.Models; using ElectroMart.API.Services; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using System.Security.Claims;
namespace ElectroMart.API.Controllers;
static class ClaimsExt{public static int Id(this ClaimsPrincipal u)=>int.Parse(u.FindFirstValue(ClaimTypes.NameIdentifier)!);}
[Authorize,ApiController,Route("api/cart")] public class CartController(CommerceService s):ControllerBase{
 [HttpGet]public async Task<IActionResult> Get()=>Ok(await s.Cart(User.Id()));[HttpPost("items")]public async Task<IActionResult>Add(AddCartItemRequest r)=>Ok(await s.AddItem(User.Id(),r));[HttpPut("items/{id:int}")]public async Task<IActionResult>Update(int id,UpdateCartItemRequest r)=>Ok(await s.UpdateItem(User.Id(),id,r));[HttpDelete("items/{id:int}")]public async Task<IActionResult>Remove(int id)=>Ok(await s.RemoveItem(User.Id(),id));[HttpDelete("clear")]public async Task<IActionResult>Clear()=>Ok(await s.Clear(User.Id()));}
[Authorize,ApiController,Route("api/orders")] public class OrdersController(CommerceService s):ControllerBase{
 [HttpPost("checkout")]public async Task<IActionResult>Checkout(CheckoutRequest r)=>Created("",await s.Checkout(User.Id(),r));[HttpGet("my-orders")]public async Task<IActionResult>Mine()=>Ok(await s.Orders(User.Id()));[HttpGet("{id:int}")]public async Task<IActionResult>Get(int id)=>(await s.Order(id,User.IsInRole("Admin")?null:User.Id())) is{} x?Ok(x):NotFound();[Authorize(Roles="Admin"),HttpGet]public async Task<IActionResult>All()=>Ok(await s.Orders());[Authorize(Roles="Admin"),HttpPut("{id:int}/status")]public async Task<IActionResult>Status(int id,StatusRequest r)=>(await s.Status(id,r.Status)) is{} x?Ok(x):NotFound();}
[Authorize(Roles="Admin"),ApiController,Route("api/admin")]public class AdminController(CommerceService s,ApplicationDbContext db):ControllerBase{[HttpGet("dashboard")]public async Task<IActionResult>Dashboard(){var o=await s.Orders();return Ok(new{totalUsers=await db.Users.CountAsync(),totalProducts=await db.Products.CountAsync(x=>x.IsActive),totalOrders=o.Count,totalSales=o.Sum(x=>x.TotalAmount),recentOrders=o.Take(5),lowStockProducts=await db.Products.Where(x=>x.IsActive&&x.StockQuantity<10).Select(x=>new{id=x.Id,name=x.Name,stockQuantity=x.StockQuantity}).ToListAsync()});}}
